            y[9] = x[39] * v[3] + x[9] * v[2];
            y[10] = x[40] * v[3] + x[10] * v[2];
            y[11] = x[41] * v[3] + x[11] * v[2];
            y[12] = x[42] * v[3] + x[12] * v[2];
            y[13] = x[43] * v[3] + x[13] * v[2];
